'use strict';
const STORAGE='aptech-ai-session7-v1';
const fresh={slide:0,answers:{},worksheet:{},manual:{w:1,b:0,x:3},selectedRow:0,listIndex:0,viewSplit:'train',exitTab:0,model:{w:0,b:0,rate:.03,kind:'straight',steps:0,history:[41],stopped:false,message:'Start with slope 0 and bias 0.'},trials:[],validation:null,sealed:null,testSeen:false};
let state;try{state={...structuredClone(fresh),...JSON.parse(localStorage.getItem(STORAGE)||'null')};}catch(e){state=structuredClone(fresh);}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true;}catch(e){return false;}}
const fmt=(v,d=2)=>Number.isFinite(v)?v.toFixed(d):'Undefined';
const sections=[{name:'The task and the learning habit',time:10,start:0},{name:'Data and Python values',time:15,start:4},{name:'Build a prediction',time:15,start:9},{name:'Measure and explain mistakes',time:15,start:13},{name:'Train the model',time:20,start:18},{name:'Validate, freeze, and test',time:15,start:22},{name:'Limits and real Python',time:15,start:27},{name:'Build, explain, and reflect',time:15,start:32}];
const sectionFor=i=>sections.filter(s=>s.start<=i).at(-1);
function dataset(kind='straight'){
 const target=x=>kind==='curve'?x*x+1:2*x+1;
 const rows=xs=>xs.map(x=>({x,y:target(x)}));
 return {train:rows([1,2,3,4]),validation:rows([5,6]),test:[7,8].map(x=>({x,y:kind==='shift'?3*x+1:target(x)}))};
}
function predict(model,x){return model.w*x+model.b;}
function scores(model,rows){if(!rows.length)return {mse:null,mae:null};return {mse:rows.reduce((sum,r)=>sum+(predict(model,r.x)-r.y)**2,0)/rows.length,mae:rows.reduce((sum,r)=>sum+Math.abs(predict(model,r.x)-r.y),0)/rows.length};}
function gradients(model,rows){const n=rows.length;return {dw:2*rows.reduce((sum,r)=>sum+(predict(model,r.x)-r.y)*r.x,0)/n,db:2*rows.reduce((sum,r)=>sum+predict(model,r.x)-r.y,0)/n};}
function nextStep(model,rows){const g=gradients(model,rows),w=model.w-model.rate*g.dw,b=model.b-model.rate*g.db,loss=scores({w,b},rows).mse;return {w,b,loss,g,valid:Number.isFinite(loss)&&loss<=1e12};}
function train(count=1){if(state.sealed||state.model.stopped)return;const rows=dataset(state.model.kind).train;state.validation=null;for(let i=0;i<count;i++){const next=nextStep(state.model,rows);if(!next.valid){state.model.stopped=true;state.model.message='Stopped: the proposed loss became too large. Reset and choose a smaller learning rate.';break;}Object.assign(state.model,{w:next.w,b:next.b,steps:state.model.steps+1});state.model.history.push(next.loss);state.model.history=state.model.history.slice(-60);state.model.message='Updated using training rows only. Latest slope '+fmt(next.w)+', bias '+fmt(next.b)+'.';}save();}
function resetModel(kind=state.model.kind,rate=state.model.rate){state.model={w:0,b:0,kind,rate,steps:0,history:[scores({w:0,b:0},dataset(kind).train).mse],stopped:false,message:'Reset to slope 0 and bias 0.'};state.validation=null;state.sealed=null;save();}
function validate(){if(state.sealed||state.model.stopped)return;const m=state.model,v=scores(m,dataset(m.kind).validation);state.validation={...v,w:m.w,b:m.b,steps:m.steps};state.trials.push({kind:m.kind,rate:m.rate,steps:m.steps,w:m.w,b:m.b,mae:v.mae});state.trials=state.trials.slice(-30);save();}
function sealAndTest(){if(state.sealed||state.model.stopped)return;const m=state.model,d=dataset(m.kind);state.sealed={w:m.w,b:m.b,kind:m.kind,steps:m.steps,rate:m.rate,train:scores(m,d.train),validation:scores(m,d.validation),test:scores(m,d.test),repeat:state.testSeen};state.testSeen=true;save();}
const panel=(title,text,cls='')=>'<div class="panel stack '+cls+'"><h3>'+title+'</h3><p>'+text+'</p></div>';
const note=text=>'<div class="note">'+text+'</div>';
function field(key,label,placeholder=''){return '<label>'+esc(label)+'<textarea class="answer" data-field="'+key+'" placeholder="'+esc(placeholder)+'">'+esc(state.worksheet[key]||'')+'</textarea></label>';}
function quiz(id){const q=quizData[id],a=state.answers[id];return '<div class="stack"><h3>'+q.q+'</h3><div class="choices">'+q.options.map((o,i)=>'<button data-quiz="'+id+'" data-choice="'+i+'" aria-pressed="'+(a===i)+'">'+o+'</button>').join('')+'</div><div id="feedback-'+id+'" class="feedback '+(a!==undefined&&a!==q.correct?'bad':'')+'" aria-live="polite">'+(a===undefined?'':(a===q.correct?'Yes. ':'Review the reason. ')+q.why)+'</div></div>';}
const quizData={
 learn:{q:'What makes this workshop’s training different from moving a slider?',options:['An update rule adjusts parameters using errors on training examples.','The computer changes a number, so every slider movement is training.'],correct:0,why:'Training here computes an error signal from examples and uses it to update the model. Manual adjustment alone is not this training procedure.'},
 split:{q:'Which data should guide the parameter updates?',options:['The training rows.','Whichever test rows make the final score look best.'],correct:0,why:'Training fits parameters, validation guides choices, and held-out test data evaluates the chosen system.'},
 bias:{q:'Both models have slope 2. One has bias 0; the other bias 1. What changes?',options:['Every prediction rises by 1 when the bias rises from 0 to 1.','Only predictions for large inputs change.'],correct:0,why:'The bias adds the same offset at every input. The slope determines the change per extra hour.'},
 error:{q:'Prediction 6, actual cost 7: with error = prediction − actual, what is the error?',options:['−1 credit: the prediction is too low.','+1 credit: the prediction is too high.'],correct:0,why:'6 − 7 = −1. The sign tells the direction; absolute error is 1 and squared error is 1.'},
 loss:{q:'Why square errors before averaging for this training loss?',options:['It prevents opposite signs cancelling and gives larger errors more influence.','It guarantees the model will predict every future cost correctly.'],correct:0,why:'MSE measures squared differences. Minimising training loss does not guarantee performance on future data.'},
 loop:{q:'Why do we calculate both gradients before changing either parameter?',options:['So both updates use the same old model.','Because Python cannot assign a variable twice.'],correct:0,why:'Our simultaneous gradient-descent step derives both changes from the pre-update parameters.'},
 rate:{q:'A larger learning rate makes the loss explode. What should you try first?',options:['Reset and use a smaller rate; inspect the loss again.','Assume a larger number proves faster learning.'],correct:0,why:'A step can overshoot. Learning rate is an update setting, not a measure of model intelligence.'},
 validate:{q:'Which choice can validation data support?',options:['Comparing candidate settings before final test evaluation.','Repeatedly rewriting the model until the test score becomes perfect.'],correct:0,why:'Use validation for choices. Test data is held aside to evaluate the selected system.'},
 shift:{q:'Training error is tiny, but later prices follow a changed policy. What follows?',options:['The old pattern may fail; investigate the new data and policy.','Tiny training error guarantees the old predictions stay accurate.'],correct:0,why:'Distribution shift can break an earlier relationship. A test result describes its particular data, not every future condition.'},
 leakage:{q:'You inspect the test answers, change the slope, and call the new test score independent. What is wrong?',options:['The test has influenced model selection. A fresh independent evaluation needs new held-out data.','Nothing: the revised score is automatically more trustworthy.'],correct:0,why:'Using evaluation answers to make choices weakens the independence of the claimed final evaluation.'},
 curve:{q:'A curved relationship keeps leaving a pattern of errors after line training. What could it mean?',options:['The straight-line model is too restrictive for that relationship.','Every remaining error must be a Python syntax mistake.'],correct:0,why:'Optimising a limited model family cannot make it represent every relationship. Inspect model fit and a suitable baseline.'},
 meaning:{q:'What does MAE = 2 credits mean on the evaluated examples?',options:['The average absolute prediction error was 2 credits on those examples.','Each future prediction is guaranteed to be within 2 credits.'],correct:0,why:'An average summarises this evaluation set; it is not a per-case bound or future guarantee.'},
 exit1:{q:'Why does a model need a target during this supervised training?',options:['The target lets us measure how far a prediction is from the desired answer.','It lets the model avoid making a prediction.'],correct:0,why:'The error compares a computed prediction with the example’s observed target.'},
 exit2:{q:'What has changed when gradient descent completes an update?',options:['The slope and bias parameters. The dataset’s recorded targets stay the same.','The actual observed cost is rewritten to match the prediction.'],correct:0,why:'We adjust the model to fit examples; we do not alter the labels merely to improve the score.'},
 exit3:{q:'What is a strong explanation of your trained model?',options:['State the input, output, update mechanism, held-out result, and a limitation.','Show a low number without explaining the data or metric.'],correct:0,why:'A useful report connects the task, mechanism, evidence, and practical limits.'}
};
Object.values(quizData).forEach((q,i)=>{if(i%2){q.options.reverse();q.correct=1-q.correct;}});
function tableRows(rows,model=null){return '<table class="table07"><thead><tr><th>Hours x</th><th>Actual y</th>'+(model?'<th>Predicted</th><th>Error</th>':'')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+r.x+'</td><td>'+r.y+'</td>'+(model?'<td>'+fmt(predict(model,r.x))+'</td><td>'+fmt(predict(model,r.x)-r.y)+'</td>':'')+'</tr>').join('')+'</tbody></table>';}
function chart(model,trainRows,held=[],xMax=8,yMax=20,highlight=null,curve=false){const left=43,top=14,width=439,height=185,X=x=>left+x/xMax*width,Y=y=>top+height-y/yMax*height;const ticks=[0,.25,.5,.75,1];return '<svg class="chart07" viewBox="0 0 500 235" role="img" aria-label="Prediction line and observed cost examples"><defs><clipPath id="plotClip07"><rect x="43" y="14" width="439" height="185"/></clipPath></defs>'+ticks.map(t=>'<line class="gridline" x1="43" y1="'+Y(t*yMax)+'" x2="482" y2="'+Y(t*yMax)+'"/><text x="35" y="'+(Y(t*yMax)+4)+'" text-anchor="end">'+fmt(t*yMax,Number.isInteger(t*yMax)?0:1)+'</text><text x="'+X(t*xMax)+'" y="216" text-anchor="middle">'+fmt(t*xMax,0)+'</text>').join('')+'<g clip-path="url(#plotClip07)"><path class="model-line" d="M '+X(0)+' '+Y(predict(model,0))+' L '+X(xMax)+' '+Y(predict(model,xMax))+'"/>'+(curve?'<path class="curve-line" d="'+Array.from({length:81},(_,i)=>{const x=i*xMax/80;return (i?'L ':'M ')+X(x)+' '+Y(x*x+1);}).join(' ')+'"/>':'')+trainRows.map((r,i)=>'<circle class="train-dot" cx="'+X(r.x)+'" cy="'+Y(r.y)+'" r="6"/>'+(i===highlight?'<line class="residual" x1="'+X(r.x)+'" y1="'+Y(r.y)+'" x2="'+X(r.x)+'" y2="'+Y(predict(model,r.x))+'"/><circle class="chosen-dot" cx="'+X(r.x)+'" cy="'+Y(predict(model,r.x))+'" r="4"/>':'')).join('')+held.map(r=>'<rect class="held-dot" x="'+(X(r.x)-5)+'" y="'+(Y(r.y)-5)+'" width="10" height="10"/>').join('')+'</g><text x="260" y="232" text-anchor="middle">Input: rental hours</text><text x="43" y="10">Credits</text></svg>';}
function slider(key,label,min,max,step,value,group='manual'){return '<div class="control07"><label for="'+group+'-'+key+'">'+label+'<output id="value-'+key+'">'+fmt(value)+'</output></label><input id="'+group+'-'+key+'" data-'+group+'="'+key+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+value+'"></div>';}
function manualHTML(mode='prediction'){return '<div class="lab07 manual-lab07"><div class="stack"><div id="manualChart"></div><p class="caption">Green circles: training observations. Solid line: current model. Dashed gap: the selected example’s error.</p>'+(mode==='prediction'?panel('The fictional relationship','Training rows: 1 hour → 3 credits, 2 → 5, 3 → 7, 4 → 9. Try to explain the pattern before adjusting the line.'):mode==='sensitivity'?'<div id="sensitivityResult" class="result07 reason07"></div>':'<div id="manualTable"></div>')+'</div><div class="stack"><div class="controls07">'+slider('w','Slope w · credits per hour',0,6,.1,state.manual.w)+slider('b','Bias b · credits',-6,4,.1,state.manual.b)+(mode==='prediction'?slider('x','Hours to predict',0,8,.5,state.manual.x):'<label class="control07">Inspect an example<select id="selectedRow">'+[1,2,3,4].map((x,i)=>'<option value="'+i+'" '+(state.selectedRow===i?'selected':'')+'>'+x+' hour'+(x>1?'s':'')+'</option>').join('')+'</select></label>')+'</div><div id="manualResult" class="result07" aria-live="polite"></div><div id="manualFormula" class="formula07"></div>'+'<div class="row"><button id="perfectManual">Try w=2, b=1</button><button id="resetManual">Reset</button></div><p class="caption">These controls manually adjust parameters. The training loop later computes its own updates.</p></div></div>';}
function updateManual(){const m=state.manual,rows=dataset().train,r=rows[state.selectedRow],v=scores(m,rows),e=predict(m,r.x)-r.y;document.getElementById('manualChart').innerHTML=chart(m,rows,[],8,30,state.selectedRow);for(const k of ['w','b','x']){const out=document.getElementById('value-'+k);if(out)out.textContent=fmt(m[k]);}const t=document.getElementById('manualTable');if(t)t.innerHTML=tableRows(rows,m);const isPrediction=state.slide===9;document.getElementById('manualResult').innerHTML=isPrediction?'<span>Prediction at '+fmt(m.x)+' hours</span><b>'+fmt(predict(m,m.x))+' credits</b>':'<span>Training MSE · squared credits</span><b>'+fmt(v.mse)+'</b><small>Training MAE = '+fmt(v.mae)+' credits</small>';document.getElementById('manualFormula').textContent=isPrediction?'prediction = w × x + b\n           = '+fmt(m.w)+' × '+fmt(m.x)+' + '+fmt(m.b)+'\n           = '+fmt(predict(m,m.x)):'Selected row: x='+r.x+', actual='+r.y+'\nprediction = '+fmt(predict(m,r.x))+'\nerror = predicted − actual = '+fmt(e)+'\nerror² = '+fmt(e*e);const sensitivity=document.getElementById('sensitivityResult');if(sensitivity){const lower=scores({...m,w:m.w-.1},rows).mse,upper=scores({...m,w:m.w+.1},rows).mse;sensitivity.textContent='Compare slope only: MSE at w−0.1 is '+fmt(lower)+'; at current w is '+fmt(v.mse)+'; at w+0.1 is '+fmt(upper)+'. Which direction helps locally?';}}
function datasetHTML(){return '<div class="lab07"><div class="stack"><div class="tabs07">'+[['train','Training · 4 rows'],['validation','Validation · 2 rows'],['test','Test · keep aside']].map(([v,n])=>'<button data-split="'+v+'" aria-pressed="'+(state.viewSplit===v)+'">'+n+'</button>').join('')+'</div><div id="datasetRows"></div><p class="caption">These are deliberately tiny, fictional chronological splits. Later hours are outside the training range. Real projects need representative examples and stronger evaluation.</p></div>'+panel('What do the two numbers mean?','x is an available input: rental hours. y is the observed total cost in credits. A label is the target answer for an example; the model’s prediction is a separate computed value.')+'</div>';}
function updateDataset(){const el=document.getElementById('datasetRows');if(state.viewSplit==='test'&&!state.sealed){el.innerHTML='<div class="seal07"><h3>Test answers are kept aside</h3><p>There are two later examples. Freeze the selected model on slide 25 before revealing their results.</p><button data-go="24">Go to freeze and test</button></div>';return;}el.innerHTML=tableRows(dataset(state.model.kind)[state.viewSplit],state.viewSplit==='test'?state.sealed:null);}
const starterLines=[['hours = 3','Assign the number 3 to a variable. There are no quotes: this value is numeric.'],['slope = 2','The parameter represents how many extra credits one extra hour adds in this model.'],['bias = 1','Add a constant offset. In our fictional pattern, this is a fixed setup charge.'],['prediction = slope * hours + bias','Multiply the hours by the slope, then add the bias. Multiplication has higher precedence than addition.'],['print(prediction)','Display the computed value. This code should print 7. It is prediction with chosen parameters, not training.']];
const loopLines=[['for step in range(500):','Repeat the indented body 500 times. A step uses the training rows, not the test answers.'],['    dw = 0.0; db = 0.0','Start two accumulators at zero for this step. The full download writes these as separate lines.'],['    for hours, actual in training:','Read each input/target pair from the training list. Indentation marks the nested loop body.'],['        error = slope * hours + bias - actual','Predict from the old model, then subtract the observed target. Do not rewrite the target.'],['        dw += 2 * error * hours / len(training)','Accumulate the slope sensitivity of the mean squared error. += adds to the existing value. This formula is explained as optional mathematics.'],['        db += 2 * error / len(training)','Accumulate the bias sensitivity. The bias affects each prediction by the same amount.'],['    slope -= learning_rate * dw','After calculating both sensitivities, move the slope opposite its gradient. -= subtracts from the stored value.'],['    bias -= learning_rate * db','Move the bias using the same old model’s gradient. The learning rate scales the update.']];
function codeLinesHTML(lines,group){return '<div class="line-buttons07">'+lines.map((_,i)=>'<button data-line-group="'+group+'" data-line="'+i+'" aria-pressed="'+(i===0)+'">Line '+(i+1)+'</button>').join('')+'</div><div id="lineDetail" class="panel stack"><pre class="code code07">'+esc(lines[0][0])+'</pre><p>'+esc(lines[0][1])+'</p></div>'+note('Predict what this line reads, computes, or changes. Explain why its place in the sequence matters.');}
function trainingHTML(){const m=state.model,locked=Boolean(state.sealed);return '<div class="lab07"><div class="stack"><div id="trainingChart"></div><div id="trainingStats" class="stats07"></div><div id="lossHistory" class="loss-history07" role="img" aria-label="Recent training loss values, on a logarithmic scale"></div><p class="caption">Green: training observations. Line: learned model. Bars: recent log(1 + MSE), scaled together. Parameters start at zero; displayed values are rounded.</p></div><div class="stack"><div class="controls07"><label class="control07">Data scenario<select id="modelKind" '+(locked?'disabled':'')+'>'+[['straight','Same straight pattern'],['shift','Later prices change'],['curve','Curved relationship']].map(([v,n])=>'<option value="'+v+'" '+(m.kind===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="control07">Learning rate<select id="learningRate" '+(locked?'disabled':'')+'>'+[[.001,'0.001 · small'],[.03,'0.03 · starter'],[.5,'0.5 · too large here']].map(([v,n])=>'<option value="'+v+'" '+(m.rate===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><div class="train-actions07"><button id="trainStep" class="accent">One update</button><button id="train50">50 updates</button><button id="train500">500 updates</button><button id="resetTraining">Reset to explore</button></div><div id="trainingMessage" class="result07" aria-live="polite"></div><div id="trainingFormula" class="formula07"></div><p id="testSeenNote" class="caption"></p></div></div>';}
function updateTraining(){const m=state.model,d=dataset(m.kind),v=scores(m,d.train),g=gradients(m,d.train);document.getElementById('trainingChart').innerHTML=chart(m,d.train,[],8,m.kind==='curve'?70:30);document.getElementById('trainingStats').innerHTML=[['Updates',m.steps],['Slope',fmt(m.w)],['Bias',fmt(m.b)]].map(([n,v])=>'<div class="stat07">'+n+'<b>'+v+'</b></div>').join('');const log=m.history.map(v=>Math.log1p(v)),max=Math.max(...log,1e-12);document.getElementById('lossHistory').innerHTML=log.map((v,i)=>'<span title="MSE '+fmt(m.history[i],4)+'" style="height:'+Math.max(2,100*v/max)+'%"></span>').join('');const msg=document.getElementById('trainingMessage');msg.textContent=state.sealed?'Model frozen. Its test result remains tied to these parameters. Reset only for further exploration.':m.message;msg.classList.toggle('bad',m.stopped);document.getElementById('trainingFormula').textContent='training MSE = '+fmt(v.mse,6)+'\nnext slope = w − rate × dw\n           = '+fmt(m.w)+' − '+m.rate+' × '+fmt(g.dw)+'\nnext bias  = '+fmt(m.b)+' − '+m.rate+' × '+fmt(g.db);for(const id of ['trainStep','train50','train500'])document.getElementById(id).disabled=Boolean(state.sealed||m.stopped);document.getElementById('testSeenNote').textContent=state.testSeen?'Test answers have been viewed. Further tuning is exploration; a new independent evaluation needs fresh held-out data.':'This loop reads only the four training rows. Validation and test rows do not supply its gradients.';}
function validationHTML(){return '<div class="lab07"><div class="stack"><div id="validationChart"></div><div class="row"><button id="runValidation" class="accent">Record validation result</button><button data-go="18">Return to training</button></div><p class="caption">Compare settings using validation. Record a reason for your choice, then freeze it. This toy dataset is too small to establish real deployment quality.</p></div><div class="stack"><div id="validationResult" class="result07" aria-live="polite"></div><div id="trialLedger" class="ledger07"></div>'+field('validationChoice','Which setting would you choose, and why?','Use validation evidence and explain a limitation.')+'</div></div>';}
function updateValidation(){const m=state.model,d=dataset(m.kind),v=state.validation;document.getElementById('validationChart').innerHTML=chart(m,d.train,d.validation,8,m.kind==='curve'?70:30);document.getElementById('validationResult').textContent=v?'Recorded validation MAE: '+fmt(v.mae,4)+' credits at '+v.steps+' updates.':'Validation targets are separate from the training gradients. Record the current model’s result.';document.getElementById('trialLedger').innerHTML=state.trials.length?'<table class="table07"><thead><tr><th>Scenario</th><th>Rate</th><th>Updates</th><th>Val MAE</th></tr></thead><tbody>'+state.trials.slice().reverse().map(t=>'<tr><td>'+esc(t.kind)+'</td><td>'+t.rate+'</td><td>'+t.steps+'</td><td>'+fmt(t.mae,4)+'</td></tr>').join('')+'</tbody></table>':'<p class="caption" style="padding:12px">No validation trials recorded yet.</p>';document.getElementById('runValidation').disabled=Boolean(state.sealed||m.stopped);}
function testHTML(){return '<div class="lab07"><div class="stack"><div id="testChart"></div><div id="testRows"></div></div><div class="stack"><div id="testResult" class="result07" aria-live="polite"></div><div class="row"><button id="sealTest" class="accent">Freeze model & reveal test</button><button data-go="18">Return to training</button></div>'+field('testReason','Explain the test result and one limit','Compare the data ranges and possible changes in the relationship.')+'<p class="caption">Freezing locks the model in this page. The examples are visible in the downloadable code; this is a teaching boundary, not a secret-data system.</p></div></div>';}
function updateTest(){const frozen=state.sealed,m=frozen||state.model,d=dataset(m.kind);document.getElementById('testChart').innerHTML=chart(m,d.train,frozen?d.test:[],8,m.kind==='curve'?70:30);document.getElementById('testRows').innerHTML=frozen?tableRows(d.test,frozen):'<div class="seal07"><h3>Two test answers kept aside</h3><p>Select your settings using training and validation. Then freeze this model before looking at the test score.</p></div>';const el=document.getElementById('testResult');el.classList.toggle('bad',Boolean(frozen&&frozen.test.mae>1));el.innerHTML=frozen?'<span>Frozen model · slope '+fmt(frozen.w)+', bias '+fmt(frozen.b)+'</span><b>Test MAE: '+fmt(frozen.test.mae,4)+' credits</b><small>Training MAE '+fmt(frozen.train.mae,4)+' · validation MAE '+fmt(frozen.validation.mae,4)+'</small><span>'+(frozen.repeat?'This is another exploration after test answers were viewed. Use fresh held-out data for a new independent claim.':'This result evaluates the selected model on these two examples only.')+'</span>':'Your model is not frozen yet. Explain your selection before revealing test results.';document.getElementById('sealTest').disabled=Boolean(frozen||state.model.stopped);}
function updateList(){const pairs=[[1,3],[2,5],[3,7],[4,9]],pair=pairs[state.listIndex];document.getElementById('listDetail').textContent='training['+state.listIndex+'] = '+JSON.stringify(pair)+'\nhours  = '+pair[0]+'\nactual = '+pair[1]+'\n\nThe first item has index 0.';document.querySelectorAll('[data-list-index]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.listIndex)===state.listIndex));}
const slide=(title,kicker,html,notes)=>({title,kicker,html,notes});
const slides=[
/* 0 */slide('Train your first model','Session 07 · additional practical workshop',()=>'<div class="grid hero07"><div class="stack"><h1>Make a prediction.<br><em>Learn from the error.</em></h1><p class="lead">Build a small model that learns a numerical relationship. Explain its code and test what it can—and cannot—do.</p><div class="row"><span class="tag">2-hour extra workshop</span><span class="tag">No API key</span><span class="tag">Offline Python</span></div></div><div class="hero-board07"><div><b>01</b>Represent the examples</div><div><b>02</b>Predict and measure</div><div><b>03</b>Update the parameters</div><div><b>04</b>Evaluate a frozen model</div></div></div>','Welcome. This additional workshop was requested after the six scheduled classroom sessions. It teaches one actual, small supervised-learning procedure without a package or API.'),
/* 1 */slide('Where this workshop belongs','An extension to the supplied manual',()=>'<div class="grid two">'+panel('Six scheduled classroom sessions','The manual allocates 12 teaching hours across six classes. Book Session 7, OpenAI coding, was covered in our Session 5.')+panel('An additional practical session','This two-hour workshop extends the ML workflow from Session 1 and the calculations from Sessions 2 and 6. Its exercises are original supplements.')+'</div>'+note('This workshop adds teaching time. It does not replace the official textbook questions or ProConnect assignments.'),'2 minutes. Keep classroom numbering distinct from book numbering. This session is an extra workshop, not an invented official seventh scheduled class.'),
/* 2 */slide('Work like a model detective','120 minutes · predict, run, change, explain',()=>'<div class="grid two">'+panel('Partner routine','One student predicts; the other operates the controls. Run the step, compare the result, and explain a changed example. Swap roles at each block.')+'<div class="panel agenda07">'+sections.map(s=>'<div class="agenda-row07"><button data-go="'+s.start+'">'+s.name+'</button><span>'+s.time+' min</span></div>').join('')+'</div></div>','The eight block durations total 120 minutes. Discuss the result before moving on. Calculus is optional stretch explanation; input, output, error, and update order are the core ideas.'),
/* 3 */slide('When does the model learn?','Start with the mechanism',()=>'<div class="grid two">'+quiz('learn')+panel('Recall the neuron lab','Earlier sliders set parameters manually. Here the program measures errors and calculates repeated updates from training examples.')+'</div>','3 minutes. Distinguish manual control, prediction, and parameter fitting. A model can predict without being trained during that prediction.'),
/* 4 */slide('A task with numbers students can inspect','Predict a fictional campus booth rental cost',()=>'<div class="grid two">'+panel('The input and target','Input x: rental hours known before the quote. Target y: the observed total cost in credits. We want a useful numerical prediction.')+panel('Start with a baseline','A simple baseline always predicts the mean training cost: 6 credits. A learned model should be compared with that baseline on the same evaluated data.')+'</div>'+note('These examples are synthetic teaching data. Real pricing decisions require the actual policy and representative records.'),'3 minutes. This is supervised regression. Explain units and what is available at prediction time. The training targets 3,5,7,9 have mean 6. A fictional price pattern is not a real campus fee policy.'),
/* 5 */slide('An example has two different jobs','Inspect training, validation, and test splits',datasetHTML,'4 minutes. x is input; y is the target. Four training, two validation, two test rows. The chronological split deliberately tests later hours. Explain extrapolation and the limits of tiny synthetic data.'),
/* 6 */slide('Numbers, names, and calculation','Your first five Python lines',()=>codeLinesHTML(starterLines,'starter'),'3 minutes. Click each line and require a value prediction. Numeric 3 differs from string "3". Multiplication precedes addition. print displays a result; this chosen-parameter example does not train.'),
/* 7 */slide('A list holds the training examples','Indexing and unpacking without mystery',()=>'<div class="grid two"><div class="stack"><pre class="code code07">training = [(1, 3), (2, 5), (3, 7), (4, 9)]\nhours, actual = training[0]</pre><div class="tabs07">'+[0,1,2,3].map(i=>'<button data-list-index="'+i+'">Index '+i+'</button>').join('')+'</div><pre id="listDetail" class="formula07"></pre></div>'+panel('Why keep a pair together?','The input and its target belong to the same example. Unpacking assigns the first value to hours and the second to actual. Swapping them changes the task.')+'</div>','3 minutes. A list keeps order; each tuple groups an input and target. Python begins indexing at zero. Explain which label belongs to each input before discussing loops.'),
/* 8 */slide('Keep the roles of the splits separate','Why the foundation matters',()=>'<div class="grid two">'+quiz('split')+'<div class="panel stack"><h3>Three purposes</h3><p>Training: fit slope and bias.</p><p>Validation: compare settings or candidate choices.</p><p>Test: evaluate the selected frozen system.</p></div></div>','2 minutes. The held-out split should not influence gradients or chosen settings. Fitting preprocessing on held-out data could also leak information in a larger workflow.'),
/* 9 */slide('Build one prediction line','Manual model lab · change a parameter',()=>manualHTML('prediction'),'6 minutes. Predict y=w*x+b. Default w1,b0,x3 gives3; the observed target is7. The fictional exact relationship is w2,b1. These sliders are manual; later training computes updates.'),
/* 10 */slide('The slope describes a change','Why multiply input by a parameter?',()=>'<div class="grid two">'+panel('One more hour','With w=2, adding one rental hour increases the model’s predicted cost by 2 credits. With w=1, it increases by 1 credit.')+'<div class="panel dark stack"><h3>Trace the difference</h3><pre class="code code07">y(3) = 2 × 3 + 1 = 7\ny(4) = 2 × 4 + 1 = 9\nchange = 9 − 7 = 2</pre><p>The slope’s units are credits per hour.</p></div></div>'+note('Act it out: each extra hour adds the slope’s number of tokens to the model’s quote.'),'3 minutes. Slope is rate of change in this linear model. It is a learned parameter when fitted; hours are the input. Do not call the slope the observed price itself.'),
/* 11 */slide('The bias supplies an offset','Why add a value after the multiplication?',()=>'<div class="grid two">'+quiz('bias')+panel('At zero hours','The expression w × 0 + b returns b. In this fictional story, bias 1 corresponds to a setup charge. A learned bias need not always have a literal business interpretation.')+'</div>','3 minutes. Contrast slope and offset through arithmetic. Zero is outside the observed 1–4 hour training inputs, so interpreting an intercept can involve extrapolation.'),
/* 12 */slide('A formula becomes a reusable function','Input, output, and return',()=>'<div class="grid two"><pre class="code code07">def predict(hours, slope, bias):\n    return slope * hours + bias\n\nquote = predict(3, 2, 1)\nprint(quote)</pre>'+panel('Explain each part','def names a reusable operation. Parameters receive caller values. The colon and indentation mark the body. return sends the result back. quote stores it; print displays it.')+'</div>'+note('Before running: what would predict(4, 2, 1) return? Why does changing the input differ from changing the slope?'),'3 minutes. Return9 for input4. A function avoids rewriting the formula. Explain assignment, multiplication, function call, and indentation before introducing nested loops.'),
/* 13 */slide('An error compares two separate values','Interactive error lab',()=>manualHTML('errors'),'5 minutes. Error = prediction−actual. Its sign distinguishes over/underprediction. Inspect each row and dashed residual. The model changes; recorded targets do not change to improve its score.'),
/* 14 */slide('Squared errors make a training objective','Mean squared error: square, add, divide',()=>'<div class="grid two">'+quiz('loss')+'<div class="panel dark stack"><h3>Start at w=0, b=0</h3><pre class="code code07">predictions: 0, 0, 0, 0\nerrors:     −3, −5, −7, −9\nsquares:     9, 25, 49, 81\nMSE = (9 + 25 + 49 + 81) / 4\n    = 41 squared credits</pre></div></div>','3 minutes. The square prevents cancellation and increases large-error influence. MSE has squared units. This is one loss choice; it does not guarantee generalisation.'),
/* 15 */slide('MAE gives a report in the target’s units','Different measures answer different questions',()=>'<div class="grid two">'+quiz('error')+panel('Mean absolute error','Take the size of each error, then average. At w=0,b=0, MAE=(3+5+7+9)/4=6 credits. Our training procedure uses MSE, while our final report also uses MAE.')+'</div>'+note('A lower reported error needs context: which examples, which units, and compared with which baseline?'),'3 minutes. Training loss and report metric need not be identical. MAE is interpretable in credits. MSE emphasises large errors; neither alone establishes task usefulness.'),
/* 16 */slide('Which direction lowers the loss nearby?','Parameter sensitivity · compare a small change',()=>manualHTML('sensitivity'),'4 minutes. Compare the MSE at w−0.1 and w+0.1 while keeping b fixed. This gives intuition for a local direction, not a replacement for the analytic gradient used in the training loop.'),
/* 17 */slide('A gradient describes local sensitivity','Optional mathematics · explain the update',()=>'<div class="grid two"><div class="panel stack"><h3>At the all-zero model</h3><p>Errors: −3, −5, −7, −9.</p><pre class="formula07">dw = mean(2 × error × hours) = −35\ndb = mean(2 × error)         = −12\n\nrate = 0.03\nnew w = 0 − 0.03 × (−35) = 1.05\nnew b = 0 − 0.03 × (−12) = 0.36</pre></div>'+panel('Why subtract?','The gradient points toward a local increase in MSE. A suitably small step in the opposite direction can reduce it. Both gradients are computed from the same old model. The rate controls the step size.')+'</div>'+note('Core skill: trace the arithmetic and update order. Deriving the gradients with calculus is optional stretch work.'),'Use within the training block discussion. Differentiate MSE optionally: d/dw(error²)=2*error*x and d/db(error²)=2*error; average across rows. At zero: dw−35,db−12. No need to memorise unexplained calculus.'),
/* 18 */slide('Now let training calculate the updates','Actual local gradient descent · training data only',trainingHTML,'8 minutes. Start zero with rate.03. One update gives w1.05,b.36 and MSE 10.21835. Use50 then500 updates to see convergence near w2,b1. Only training rows drive gradients. This is real small linear-model fitting in JavaScript; Python reproduces it.'),
/* 19 */slide('Why this loop has this order','Trace the Python training body',()=>codeLinesHTML(loopLines,'loop'),'4 minutes. Reinitialise accumulators at each outer step, read all training pairs, compute both gradients, then update both parameters. The full Python file writes accumulator assignments on separate lines and explains indentation.'),
/* 20 */slide('Two gradients must use the same old model','Explain the dependency before copying the code',()=>'<div class="grid two">'+quiz('loop')+panel('A learning rate is a setting','Small can be slow. Large can overshoot. The suitable range depends on feature scaling, data, loss, and the update rule; 0.03 is only a starter for this example.')+'</div>','3 minutes. Show which variables change and which remain example values. Rate is a hyperparameter. No claim that the chosen rate works for every dataset or every algorithm.'),
/* 21 */slide('Try to break the training','Learning-rate debugging mission',()=>'<div class="grid two">'+quiz('rate')+'<div class="panel stack"><h3>Experiment in the lab</h3><p>Reset. Choose rate 0.5. Run 50 updates and inspect the warning.</p><p>Reset with 0.001, then 0.03. Compare convergence after the same update count.</p><button data-go="18" class="primary">Open the training lab</button></div></div>'+note('The lab stops before a proposed loss exceeds its numerical limit. A warning is a debugging observation, not successful training.'),'5 minutes. At large rate, loss rapidly increases; the guard stops a proposed invalid or enormous step. Reset before comparing rates because continued training would start from different parameters.'),
/* 22 */slide('Validation supports a choice','Keep final test evidence aside',()=>'<div class="grid two">'+quiz('validate')+panel('Use a fair comparison','Reset each candidate to the same initial parameters. Compare rate and update-count choices using validation MAE. Write a reason for selection before inspecting test answers.')+'</div>','3 minutes. Validation guides setting choices. A reset clears the active candidate but retains trial records for comparison. Repeated extensive validation tuning can also overfit validation; this tiny lab is demonstrative.'),
/* 23 */slide('Record your validation trials','Compare candidate settings with evidence',validationHTML,'6 minutes. Orange squares are validation examples; green circles are training. The ledger records scenario, rate, steps, and validation MAE. Return to training to reset a candidate. Separate scenarios before comparing.'),
/* 24 */slide('Freeze first, then inspect the test','Hold-out evaluation of a fixed model',testHTML,'6 minutes. Freezing copies w,b,scenario,rate,steps and report metrics, then locks training controls. Test predictions use this snapshot. Reset is allowed for exploration, with a persistent reminder that these test answers have been seen.'),
/* 25 */slide('Small training error can still miss later prices','A deliberately changed data relationship',()=>'<div class="grid two">'+quiz('shift')+'<div class="panel stack"><h3>Try the changed-policy scenario</h3><p>Training and validation follow the earlier straight pattern. Later test prices change.</p><p>Reset the lab, choose “Later prices change”, train, then freeze and inspect. Explain why a training success can coexist with a test failure.</p><button data-go="18">Open the training lab</button></div></div>','Use as the test discussion. The shift case uses train/validation y=2x+1; test y=3x+1. Near-perfect w2,b1 predicts15,17 against22,25: test MAE≈7.5 credits. This deliberate shift illustrates a limit, not real measured pricing data.'),
/* 26 */slide('An independent score has a dependency too','Leakage detective challenge',()=>'<div class="grid two">'+quiz('leakage')+panel('A practical next step','After seeing test failures, investigate the cause and improve the system. Evaluate the revised choice on suitable fresh data before making a new independent performance claim.')+'</div>'+note('The workshop permits exploration after reset and labels it accordingly. It cannot restore the independence of already viewed examples.'),'Explain why fixing a system is useful while reusing inspected test answers weakens an independence claim. A deliberate classroom reveal does not provide cryptographic secrecy or production-grade experiment tracking.'),
/* 27 */slide('A straight line cannot represent every pattern','Model-family limits',()=>'<div class="grid two">'+quiz('curve')+'<div class="panel stack"><h3>Try the curved scenario</h3><p>Reset and choose “Curved relationship”. Training observations follow a curved pattern.</p><p>A fitted line leaves a systematic error pattern. More updates can improve optimisation while still leaving this model-family limit.</p><button data-go="18">Inspect the curved data</button></div></div>','4 minutes. Curve data y=x²+1. The best training line on x1..4 is w5,b−4 with MSE1; no line fits all four exactly. Later predictions extrapolate poorly. Discuss model fit before recommending more complexity.'),
/* 28 */slide('Report what the evidence actually means','A score is a statement about evaluated examples',()=>'<div class="grid two">'+quiz('meaning')+panel('A usable report','State the task, input availability, data split, model, training choices, baseline, metric units, result, and one limitation. Keep a fictional exercise separate from a real deployment claim.')+'</div>','3 minutes. An average error does not bound every future error. Real deployment would require representative data, error analysis, costs, and monitoring appropriate to the task.'),
/* 29 */slide('Run the matching Python model offline','Real code · no SDK or API',()=>'<div class="grid two"><div class="panel stack"><h3>Extract and run</h3><pre class="code code07">python session07_train.py\npython session07_train.py --scenario shift\npython session07_train.py --scenario curve</pre><div class="portfolio07"><a href="session-07-python.zip" download>Download Python bundle</a><a href="session07_train.py" download>Commented source</a></div></div>'+panel('Compare the same calculation','The Python program starts at w0,b0 and uses 500 updates at rate0.03. It reports training, validation, test, and baseline errors. The HTML runs JavaScript; this file runs Python in your terminal.')+'</div>','4-minute launch. No external packages or network. On Windows, py may replace python. The ZIP guide explains each argument. Use the same rate, steps, and scenario when comparing browser and Python.'),
/* 30 */slide('Connect the complete program to its purpose','Five parts with five jobs',()=>'<div class="grid two"><div class="panel stack"><h3>The program’s structure</h3><p>Data lists hold examples.</p><p>predict computes an output.</p><p>metrics reports differences.</p><p>fit adjusts parameters.</p><p>main trains, selects the demonstration configuration, and reports held-out results.</p></div>'+panel('Before changing a line','Identify whether it changes data, model behaviour, an update setting, or evaluation. Read comments to explain why the line belongs there. Full syntax explanations are in the downloaded guide.')+'</div>'+note('No package, chatbot, or neural network is required for this one small supervised-learning model.'),'4 minutes. Distinguish training from inference and evaluation. main uses a demonstration configuration rather than claiming automatic model selection. Comments cover functions, loops, dictionaries, arithmetic, CLI parsing, and the main guard.'),
/* 31 */slide('A baseline gives “better” a reference','Always predict the training mean',()=>'<div class="grid two"><div class="panel stack"><h3>The simple competitor</h3><p>The straight training targets average to 6 credits. Predict 6 for every evaluated input.</p><p>Compare its MAE with the learned model’s MAE on exactly the same test rows.</p></div>'+panel('Why this matters','A complicated system can still underperform a simple baseline. In the shifted-policy case, the line’s score worsens; comparing with the baseline gives additional context.')+'</div>'+note('Compute the mean using training targets. Do not fit the baseline to the test answers.'),'Use during Python report review. Straight test targets15,17: constant6 baseline MAE10. Shift targets22,25: baseline17.5; model about7.5. Curve baseline mean8.5; test50,65 baseline49. Low score relative to baseline still needs task context.'),
/* 32 */slide('Mission 1: train and explain a model','Practical assignment · evidence before confidence',()=>'<div class="grid two"><div class="panel stack"><h3>Your deliverable</h3><ol><li>State x, y, and their units.</li><li>Trace one update from w0,b0.</li><li>Compare two settings using validation.</li><li>Freeze a chosen model and report test MAE.</li><li>Explain one changed-data case.</li></ol><a class="assignment-link07" href="session-07-assignments.html">Open the full assignment pack</a></div><div class="report07">'+field('modelReport','Your training and evaluation report','Include calculations, validation evidence, test result, and a limit.')+'</div></div>','6 minutes. Grade reasoning and reproducibility. If test answers have already been viewed, label subsequent work exploratory. Require meaningful input/target definitions rather than only screenshots of a score.'),
/* 33 */slide('Mission 2: transfer the foundations','Design a new beginner regression task',()=>'<div class="grid two">'+panel('A new scenario','Predict event attendance or equipment rental cost. Define an input available at prediction time, a numeric target, a baseline, and what could change the relationship.')+'<div class="report07">'+field('transferPlan','Your task, examples, evaluation plan, and changed case','Explain which parts of the program would change and why.')+'</div></div>'+note('Use synthetic or approved non-sensitive data for practice. Do not invent a real performance claim from a tiny demonstration.'),'4 minutes. A design is enough in this short activity. Optional stretch: replace the Python data with another small explained numeric example. Task and label quality matter before model complexity.'),
/* 34 */slide('Peer review: require the reason','A 10-point formative rubric',()=>'<div class="grid two"><table class="table07"><thead><tr><th>Evidence to inspect</th><th>Points</th></tr></thead><tbody><tr><td>Task, input, target, units</td><td>2</td></tr><tr><td>One explained prediction and update</td><td>2</td></tr><tr><td>Split roles and validation choice</td><td>2</td></tr><tr><td>Test result plus baseline</td><td>2</td></tr><tr><td>Changed case and limitation</td><td>2</td></tr></tbody></table>'+panel('Partner questions','What value does this line read? What does it change? Why is the target unchanged? Which examples support the score? What would a changed pricing policy do?')+'</div>','2 minutes. This is a suggested formative rubric, not an official exam scheme. Require an explanation or demonstration, not a copied script or self-reported tick.'),
/* 35 */slide('Exit ticket: explain what learned','Three checks with reasons',()=>'<div class="tabs07">'+['exit1','exit2','exit3'].map((id,i)=>'<button data-exit-tab="'+i+'" aria-pressed="'+(state.exitTab===i)+'">Question '+(i+1)+'</button>').join('')+'</div><div class="grid two">'+quiz(['exit1','exit2','exit3'][state.exitTab])+panel('Show understanding','Answer all three, then explain a new example to a partner. A correct choice is the start of an explanation, not proof of mastery.')+'</div>','2 minutes. Check target/error, parameters versus data, and evidence-based explanation. Revisit specific misunderstandings using Contents.'),
/* 36 */slide('Keep the model and the explanation','Your workshop portfolio',()=>'<div class="grid two">'+panel('The habit to keep','Define the task. Inspect the data. Predict. Measure. Update from training. Choose using validation. Evaluate a frozen model. Explain the limits.','dark')+'<div class="stack">'+field('reflection','What can you now explain, and what will you practise next?','Name a concrete calculation, code line, or changed case.')+'<div class="row"><button id="downloadWork" class="primary">Download my workshop report</button><button id="downloadModel">Download model JSON</button></div><div class="portfolio07"><a href="session-07-python.zip" download>Python bundle</a><button id="scopeBtn">Scope and teacher references</button></div></div></div>','End of this additional 120-minute workshop. Model JSON contains learned parameters and evaluation context, not a runnable Python package. The report includes original worksheets and saved trials. Official core-course assignments remain separate.')
];
const glossary=[['Regression','Predict a numeric target from input information.'],['Feature','An input value available to the prediction task.'],['Target','The observed answer used to compare with a prediction in supervised learning.'],['Parameter','A value fitted by training; here slope and bias.'],['Slope','The change in predicted credits per extra hour in this linear model.'],['Bias','The constant offset added to a weighted input.'],['Prediction','A computed output from inputs and current parameters.'],['Error','Prediction minus actual target in this workshop.'],['MSE','Mean squared error: average squared prediction difference, in squared target units.'],['MAE','Mean absolute error: average absolute prediction difference, in target units.'],['Gradient','Local sensitivity of the loss to a parameter; here derived from training MSE.'],['Gradient descent','Repeatedly subtract a scaled gradient from parameters.'],['Learning rate','A setting controlling the size of a parameter update.'],['Training split','Examples used to fit the parameters.'],['Validation split','Separate examples used to compare candidate choices before final evaluation.'],['Test split','Examples kept aside to evaluate the selected model.'],['Baseline','A simple reference prediction method for comparison.'],['Extrapolation','Prediction outside the range represented by training inputs.'],['Distribution shift','A change in the data relationship or distribution relative to earlier examples.'],['Underfitting','A model is too restrictive to represent important data structure.'],['Leakage','Inappropriate information influences fitting or selection and weakens evaluation.'],['Inference','Compute outputs from a fitted model without updating it.'],['Tuple','An ordered group of values, used here for an input/target pair.'],['List','An ordered Python collection, indexed starting at zero.'],['Synthetic data','Invented examples for teaching or experimentation, not real observed records.']];
const stage=document.getElementById('stage');let lastFocus=null,seconds=7200,timerRunning=false,timerInterval=null;
function go(i){state.slide=Math.max(0,Math.min(slides.length-1,Number(i)||0));save();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const i=state.slide,s=slides[i];document.title='Session 07 · '+s.title;stage.innerHTML='<article class="slide session07"><div class="slide-head"><div class="section-label"><span class="rule"></span><span class="eyebrow">'+esc(s.kicker)+'</span></div>'+(i===0?'':'<h2>'+esc(s.title)+'</h2>')+'</div>'+s.html()+'</article>';document.getElementById('pageLabel').textContent=(i+1)+' / '+slides.length+' · '+sectionFor(i).name;document.getElementById('prevBtn').disabled=i===0;document.getElementById('nextBtn').disabled=i===slides.length-1;document.getElementById('progressFill').style.width=(i+1)/slides.length*100+'%';document.getElementById('progress').setAttribute('aria-valuenow',i+1);document.getElementById('progress').setAttribute('aria-valuemax',slides.length);if(i===5)updateDataset();if(i===7)updateList();if([9,13,16].includes(i))updateManual();if(i===18)updateTraining();if(i===23)updateValidation();if(i===24)updateTest();}
function downloadText(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadWork(){const parts=['FOUNDATIONS OF AI · SESSION 07','Additional original practical workshop · not official textbook work',new Date().toLocaleDateString()];for(const [k,title] of Object.entries({validationChoice:'Validation choice',testReason:'Test interpretation',modelReport:'Training/evaluation report',transferPlan:'New task design',reflection:'Reflection'}))parts.push(title+'\n'+(state.worksheet[k]||'[Not answered]'));parts.push('CURRENT TRAINING MODEL\n'+JSON.stringify(state.model,null,2),'VALIDATION TRIALS\n'+JSON.stringify(state.trials,null,2),'FROZEN MODEL AND TEST RESULT\n'+JSON.stringify(state.sealed||'[Not frozen]',null,2),'Test examples have been seen: '+state.testSeen,'QUIZ RECORD');for(const [id,q] of Object.entries(quizData))parts.push(id+': '+(state.answers[id]===undefined?'not answered':state.answers[id]===q.correct?'correct':'review needed'));parts.push('Tiny synthetic examples illustrate mechanisms, not real deployment performance. Subsequent tuning after test reveal is exploration.');downloadText('session-07-my-model-report.txt',parts.join('\n\n'));}
function downloadModel(){const m=state.sealed||state.model;downloadText('session-07-model.json',JSON.stringify({format:'aptech-linear-regression-v1',formula:'prediction = slope * hours + bias',inputUnits:'hours',outputUnits:'fictional credits',slope:m.w,bias:m.b,scenario:m.kind,steps:m.steps,learningRate:m.rate,frozen:Boolean(state.sealed),evaluation:state.sealed?{train:m.train,validation:m.validation,test:m.test,repeat:m.repeat}:null,testSeen:state.testSeen},null,2),'application/json');}
function timerText(){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function updateTimer(){const v=document.getElementById('timerValue'),b=document.getElementById('timerToggle');if(v)v.textContent=timerText();if(b)b.textContent=timerRunning?'Pause':'Start';}
function glossaryHTML(q=''){return glossary.filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase())).map(([w,m])=>'<div class="glossary-item"><b>'+esc(w)+'</b><p>'+esc(m)+'</p></div>').join('')||'<p>No matching term.</p>';}
function openDrawer(type){lastFocus=document.activeElement;document.getElementById('drawer').hidden=false;const title=document.getElementById('drawerTitle'),body=document.getElementById('drawerBody');if(type==='notes'){title.textContent='Teacher notes · '+(state.slide+1);body.innerHTML='<span class="teacher-pill">'+esc(sectionFor(state.slide).name)+' · '+sectionFor(state.slide).time+'-minute block</span><h3>'+esc(slides[state.slide].title)+'</h3><p>'+esc(slides[state.slide].notes)+'</p><hr class="divider"><h3>Require the mechanism</h3><p>Ask what the line reads, computes, or changes; what evidence drives an update; and which data supports the result.</p>';}else if(type==='outline'){title.textContent='Session contents';body.innerHTML='<div class="panel stack"><h3>120-minute workshop timer</h3><b id="timerValue">'+timerText()+'</b><div class="row"><button id="timerToggle">'+(timerRunning?'Pause':'Start')+'</button><button id="timerReset">Reset 120 min</button></div></div>'+slides.map((s,i)=>'<button class="outline-button '+(i===state.slide?'current':'')+'" data-outline-go="'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(s.title)+'</button>').join('');}else if(type==='scope'){title.textContent='Workshop scope and teacher reading';body.innerHTML='<p>The supplied April 2026 Aptech manual schedules six two-hour classes and six self-study hours. Its Book Session 7 is OpenAI coding, taught in our classroom Session 5.</p><p>This Session 7 is an additional two-hour practical workshop requested after those core classes. Exercises are original supplements. It does not establish completion of the missing official textbook questions or ProConnect assignments.</p><p>Browser labs use JavaScript to fit one linear model with full-batch gradient descent. The matching Python program uses only the standard library. Neither calls an API or trains a language model.</p><p>All datasets are fictional. The toy splits deliberately demonstrate extrapolation, changed relationships, and model-family limits. They do not establish reliable real pricing predictions.</p><a href="https://scikit-learn.org/stable/modules/linear_model.html" target="_blank" rel="noopener">Teacher reading: linear models</a><a href="https://scikit-learn.org/stable/common_pitfalls.html" target="_blank" rel="noopener">Teacher reading: leakage and common pitfalls</a><a href="https://docs.python.org/3/tutorial/" target="_blank" rel="noopener">Python tutorial</a><a href="session-01.html">Session 1: the ML workflow</a>';}else{title.textContent='Word bank';body.innerHTML='<label for="wordSearch" class="small">Find a term</label><input id="wordSearch" type="text" placeholder="Gradient, bias, test…"><div id="wordList">'+glossaryHTML()+'</div>';}document.getElementById('closeDrawer').focus();}
function closeDrawer(){document.getElementById('drawer').hidden=true;if(lastFocus?.isConnected)lastFocus.focus();}
stage.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go!==undefined)return go(b.dataset.go);if(b.dataset.quiz){const id=b.dataset.quiz,a=Number(b.dataset.choice),q=quizData[id];state.answers[id]=a;save();document.querySelectorAll('[data-quiz="'+id+'"]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.choice)===a));const f=document.getElementById('feedback-'+id);f.textContent=(a===q.correct?'Yes. ':'Review the reason. ')+q.why;f.classList.toggle('bad',a!==q.correct);}if(b.dataset.split){state.viewSplit=b.dataset.split;save();render();}if(b.dataset.listIndex!==undefined){state.listIndex=Number(b.dataset.listIndex);save();updateList();}if(b.dataset.line!==undefined){const lines=b.dataset.lineGroup==='starter'?starterLines:loopLines,i=Number(b.dataset.line);document.querySelectorAll('[data-line]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('lineDetail').innerHTML='<h3>Line '+(i+1)+'</h3><pre class="code code07">'+esc(lines[i][0])+'</pre><p>'+esc(lines[i][1])+'</p>';}if(b.id==='perfectManual'||b.id==='resetManual'){state.manual=b.id==='perfectManual'?{...state.manual,w:2,b:1}:structuredClone(fresh.manual);save();render();}if(['trainStep','train50','train500'].includes(b.id)){train(b.id==='trainStep'?1:b.id==='train50'?50:500);updateTraining();}if(b.id==='resetTraining'){resetModel();render();}if(b.id==='runValidation'){validate();updateValidation();}if(b.id==='sealTest'){sealAndTest();updateTest();}if(b.dataset.exitTab!==undefined){state.exitTab=Number(b.dataset.exitTab);save();render();}if(b.id==='downloadWork')downloadWork();if(b.id==='downloadModel')downloadModel();if(b.id==='scopeBtn')openDrawer('scope');});
stage.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){state.worksheet[t.dataset.field]=t.value;save();}if(t.dataset.manual){state.manual[t.dataset.manual]=Number(t.value);save();updateManual();}});
stage.addEventListener('change',e=>{const t=e.target;if(t.id==='selectedRow'){state.selectedRow=Number(t.value);save();updateManual();}if(t.id==='modelKind'&&!state.sealed){resetModel(t.value);render();}if(t.id==='learningRate'&&!state.sealed){state.model.rate=Number(t.value);state.validation=null;save();updateTraining();}});
document.getElementById('prevBtn').onclick=()=>go(state.slide-1);document.getElementById('nextBtn').onclick=()=>go(state.slide+1);document.getElementById('outlineBtn').onclick=()=>openDrawer('outline');document.getElementById('glossaryBtn').onclick=()=>openDrawer('glossary');document.getElementById('teacherBtn').onclick=()=>openDrawer('notes');document.getElementById('closeDrawer').onclick=closeDrawer;document.getElementById('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){document.getElementById('fullscreenBtn').textContent='Use browser full screen';}};
document.getElementById('drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer();const b=e.target.closest('button');if(!b)return;if(b.dataset.outlineGo!==undefined){closeDrawer();go(b.dataset.outlineGo);}if(b.id==='timerToggle'){timerRunning=!timerRunning;if(timerRunning)timerInterval=setInterval(()=>{if(seconds>0)seconds--;else{timerRunning=false;clearInterval(timerInterval);}updateTimer();},1000);else clearInterval(timerInterval);updateTimer();}if(b.id==='timerReset'){seconds=7200;timerRunning=false;clearInterval(timerInterval);updateTimer();}});
document.getElementById('drawer').addEventListener('input',e=>{if(e.target.id==='wordSearch')document.getElementById('wordList').innerHTML=glossaryHTML(e.target.value);});
document.addEventListener('keydown',e=>{const drawer=document.getElementById('drawer');if(e.key==='Escape'&&!drawer.hidden){closeDrawer();return;}if(!drawer.hidden){if(e.key==='Tab'){const all=[...drawer.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowRight'){e.preventDefault();go(state.slide+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.slide-1);}if(e.key==='Home'){e.preventDefault();go(0);}if(e.key==='End'){e.preventDefault();go(slides.length-1);}if(e.key.toLowerCase()==='n')openDrawer('notes');});
state.slide=Math.max(0,Math.min(slides.length-1,Number(state.slide)||0));state.exitTab=Math.max(0,Math.min(2,Number(state.exitTab)||0));const linkedSlide=Number(new URLSearchParams(location.search).get('slide'));if(Number.isInteger(linkedSlide)&&linkedSlide>=1&&linkedSlide<=slides.length)state.slide=linkedSlide-1;render();
